    def test_xss_script_injection_sanitized(self, component, mock_dompurify, mock_recharts):
        """Test that malicious script tags in names are sanitized."""
        mock_dompurify.sanitize.side_effect = lambda x: x.replace("<script>", "").replace("</script>", "")
        malicious_data = [
            {'name': '<script>alert("XSS")</script>CPU', 'value': 90}
        ]
        component(data=malicious_data)
        
        # Verify DOMPurify was called
        mock_dompurify.sanitize.assert_called()
        # Verify sanitized data passed to chart
        passed_data = mock_recharts.BarChart.call_args.kwargs['data']
        assert "<script>" not in passed_data[0]['name']
        assert "alert" not in passed_data[0]['name']

    def test_xss_event_handler_injection_sanitized(self, component, mock_dompurify, mock_recharts):
        """Test that event handler injection attempts are neutralized."""
        mock_dompurify.sanitize.side_effect = lambda x: x.replace("onerror=", "data-sanitized=")
        malicious_data = [
            {'name': '<img src=x onerror=alert(1)>Memory', 'value': 50}
        ]
        component(data=malicious_data)
        
        passed_data = mock_recharts.BarChart.call_args.kwargs['data']
        assert "onerror=" not in passed_data[0]['name']
        assert "data-sanitized=" in passed_data[0]['name']

